<script lang="ts">
  import type { Club, Event, ManagedCallsign } from './types';

  let { identities, clubs, events }: { identities: ManagedCallsign[]; clubs: Club[]; events: Event[] } = $props();
  let filter = $state<'all' | 'personal' | 'club' | 'special'>('all');
  let query = $state('');
  let selectedId = $state<string | null>(null);
  let visible = $derived(identities.filter((identity) => {
    const typeMatches = filter === 'all' || identity.identity_type === filter;
    const text = [identity.callsign, identity.identity_type, identity.status, identity.verification_status].join(' ').toLowerCase();
    return typeMatches && (!query.trim() || text.includes(query.trim().toLowerCase()));
  }));
  let selected = $derived(identities.find((identity) => identity.id === selectedId) || visible[0]);
  let identityClub = $derived(clubs.find((club) => club.id === selected?.club_id));
  let identityEvent = $derived(events.find((event) => event.id === selected?.event_id));

  $effect(() => {
    if (!selectedId || !identities.some((identity) => identity.id === selectedId)) selectedId = identities[0]?.id || null;
  });

  function stateLabel(identity: ManagedCallsign): string {
    if (identity.status !== 'active') return identity.status;
    return identity.verification_status === 'verified' ? 'ready' : identity.verification_status;
  }
</script>

<section class="identity-workspace">
  <div class="workspace-heading"><div><p class="eyebrow">MY OPERATING IDENTITIES</p><h1>Callsign registry</h1><p>Select a callsign to inspect its authority, scope, readiness, and the controls that govern its use.</p></div><div class="identity-totals"><span><b>{identities.filter((identity) => stateLabel(identity) === 'ready').length}</b> ready</span><span><b>{identities.filter((identity) => stateLabel(identity) !== 'ready').length}</b> needs review</span></div></div>
  <div class="toolbar"><label class="search"><span>Search</span><input bind:value={query} placeholder="Callsign or state" /></label><div class="segmented" aria-label="Filter station identities">{#each ['all', 'personal', 'club', 'special'] as item}<button class:active={filter === item} onclick={() => filter = item as typeof filter}>{item}</button>{/each}</div></div>
  {#if visible.length === 0}<div class="empty-state shallow"><span>◌</span><h2>No matching identities</h2><p>Personal identities are created from the operator account. Club and special identities require a managed organization or event.</p></div>
  {:else}<div class="identity-layout"><div class="identity-grid">{#each visible as identity}<button class:selected={identity.id === selected?.id} class:ready={stateLabel(identity) === 'ready'} class="identity-card" onclick={() => selectedId = identity.id}><div class="identity-card-head"><span class="identity-type">{identity.identity_type}</span><span class:pending={stateLabel(identity) !== 'ready'} class="state">{stateLabel(identity)}</span></div><b>{identity.callsign}</b><dl><div><dt>Authority</dt><dd>{identity.authority || 'managed record'}</dd></div><div><dt>Available</dt><dd>{new Date(identity.effective_from).toLocaleDateString()}{identity.expires_at ? ' until ' + new Date(identity.expires_at).toLocaleDateString() : ' onward'}</dd></div>{#if identity.event_id}<div><dt>Scope</dt><dd>Event-bound identity</dd></div>{/if}</dl></button>{/each}</div>
    {#if selected}<aside class="identity-inspector"><p class="eyebrow">SELECTED IDENTITY</p><div class="inspector-heading"><h2>{selected.callsign}</h2><span class:pending={stateLabel(selected) !== 'ready'} class="state">{stateLabel(selected)}</span></div><p class="inspector-lede">{selected.identity_type === 'personal' ? 'Personal operating identity tied to this operator account.' : selected.identity_type === 'club' ? 'Organization identity available through active club membership and assignment rules.' : 'Special identity bound to a specific operation and subject to its authorization rules.'}</p><dl class="inspector-facts"><div><dt>Authority</dt><dd>{selected.authority || 'Managed server record'}</dd></div><div><dt>Identity class</dt><dd>{selected.identity_type}</dd></div><div><dt>Validity</dt><dd>{new Date(selected.effective_from).toLocaleString()}{selected.expires_at ? ' until ' + new Date(selected.expires_at).toLocaleString() : ' onward'}</dd></div><div><dt>Verification</dt><dd>{selected.verification_status}</dd></div>{#if identityClub}<div><dt>Organization</dt><dd>{identityClub.name} · your role {identityClub.my_role || 'member'}</dd></div>{/if}{#if identityEvent}<div><dt>Operation</dt><dd>{identityEvent.name} · {identityEvent.status}</dd></div>{/if}</dl><section class="identity-controls"><p class="eyebrow">OPERATING CONTROLS</p>{#if stateLabel(selected) === 'ready'}<p>This callsign can be selected only when its owning scope permits it. Event use also checks active assignment, event window, band, mode, and operator role before accepting a log.</p>{:else}<p>This callsign is not currently usable for an operating assignment. Resolve its status with the owning organization or a server administrator; status changes are intentionally server-authoritative.</p>{/if}</section><section class="identity-activity"><p class="eyebrow">ACTIVITY</p><p>Contact history is retained with submitted logs and event scorekeeping. This console does not infer misleading totals from a displayed callsign when an operator has multiple valid identities.</p></section></aside>{/if}</div>{/if}
  <aside class="guidance"><b>How this works</b><p>Selecting a callsign in QSONaut never changes the authenticated operator. Event operation also requires an active station assignment, an active club membership, and the event’s time, band, and mode rules.</p></aside>
</section>

<style>
  .identity-workspace { display:grid; gap:24px; }.workspace-heading { display:flex; align-items:end; justify-content:space-between; gap:24px; }.workspace-heading h1 { margin:4px 0 8px; font-size:clamp(28px,4vw,46px); }.workspace-heading p { max-width:650px; margin:0; color:var(--muted); line-height:1.55; }.identity-totals { display:flex; gap:10px; }.identity-totals span { min-width:94px; display:grid; gap:2px; padding:12px 15px; border:1px solid var(--line); color:var(--muted); font:600 10px ui-monospace; text-transform:uppercase; }.identity-totals b { color:var(--cyan); font-size:20px; }.toolbar { display:flex; align-items:end; justify-content:space-between; gap:16px; padding:14px; border:1px solid var(--line); background:var(--panel); }.search { flex:1; max-width:480px; }.search span { font:600 10px ui-monospace; color:var(--muted); text-transform:uppercase; }.segmented { display:flex; border:1px solid var(--line); overflow:auto; }.segmented button { border:0; border-right:1px solid var(--line); padding:10px 13px; background:transparent; color:var(--muted); font:600 10px ui-monospace; text-transform:uppercase; cursor:pointer; }.segmented button.active { background:var(--cyan-dim); color:var(--cyan); }.identity-layout { display:grid; grid-template-columns:minmax(0,1.35fr) minmax(300px,.65fr); gap:16px; align-items:start; }.identity-grid { display:grid; grid-template-columns:repeat(auto-fill,minmax(230px,1fr)); gap:12px; }.identity-card { min-height:205px; display:grid; align-content:start; gap:17px; padding:18px; border:1px solid var(--line); background:var(--panel); color:var(--text); text-align:left; }.identity-card:hover,.identity-card.selected { border-color:var(--cyan); background:color-mix(in srgb,var(--panel) 88%,var(--cyan-dim)); }.identity-card.ready { border-top:2px solid var(--green); }.identity-card-head,.inspector-heading { display:flex; justify-content:space-between; align-items:start; gap:12px; }.identity-type,.state { color:var(--cyan); font:600 10px ui-monospace; letter-spacing:.08em; text-transform:uppercase; }.state.pending { color:var(--amber); }.identity-card > b,.inspector-heading h2 { font:600 26px ui-monospace; letter-spacing:-.04em; }.inspector-heading h2 { margin:3px 0 12px; } dl { display:grid; gap:9px; margin:0; } dl div { display:grid; gap:2px; } dt { color:var(--muted); font:600 9px ui-monospace; letter-spacing:.08em; text-transform:uppercase; } dd { margin:0; color:#b8cbd0; font-size:12px; }.identity-inspector { position:sticky; top:18px; padding:20px; border:1px solid var(--line); background:var(--panel); }.inspector-lede { color:var(--muted); line-height:1.55; }.inspector-facts { padding:14px 0; border-top:1px solid var(--line); border-bottom:1px solid var(--line); }.identity-controls,.identity-activity { margin-top:16px; padding:14px; background:var(--chip); }.identity-controls p,.identity-activity p { margin:5px 0; color:var(--muted); line-height:1.5; }.guidance { padding:17px 19px; border-left:2px solid var(--amber); background:color-mix(in srgb,var(--amber) 7%,var(--panel)); }.guidance p { margin:6px 0 0; max-width:900px; color:var(--muted); line-height:1.55; } @media (max-width:900px) { .identity-layout { grid-template-columns:1fr; }.identity-inspector { position:static; } } @media (max-width:700px) { .workspace-heading,.toolbar { align-items:stretch; flex-direction:column; } .search { max-width:none; } .identity-totals { justify-content:stretch; } .identity-totals span { flex:1; } }
</style>
